function insertionSort(input) {
  const a = input.slice();
  let shifts = 0;
  for (let i = 1; i < a.length; i++) {
    const key = a[i];
    let j = i - 1;
    while (j >= 0 && a[j] > key) {
      a[j + 1] = a[j];
      j--;
      shifts++;
    }
    a[j + 1] = key;
  }
  console.log(JSON.stringify(a) + "  shifts=" + shifts);
  return a;
}

